const rs = await Promise.allSettled([
  tools.exec_command({cmd:"git status --short && git rev-parse --show-toplevel","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name package.json -o -name go.mod -o -name Cargo.toml | head -100","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"ls -la","workdir":"/app","yield_time_ms":10000,"max_output_tokens":3000})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

const rs = await Promise.allSettled([
  tools.exec_command({cmd:"grep -R -n --exclude-dir=node_modules --exclude-dir=.git 'splitBySeparator' applications packages","workdir":"/app","yield_time_ms":10000,"max_output_tokens":5000}),
  tools.exec_command({cmd:"grep -R -n --exclude-dir=node_modules --exclude-dir=.git 'inputToRecipient' applications packages","workdir":"/app","yield_time_ms":10000,"max_output_tokens":5000})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

const rs = await Promise.allSettled([
  tools.exec_command({cmd:"grep -R -n 'splitBySeparator' applications packages","workdir":"/app","yield_time_ms":10000,"max_output_tokens":6000}),
  tools.exec_command({cmd:"grep -R -n 'inputToRecipient' applications packages","workdir":"/app","yield_time_ms":10000,"max_output_tokens":6000})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

